RSpec.describe Timekeeping::Handoff::MonolithStore do
  let(:connection) { ActiveRecord::Base.connection }

  def round_trip_seed
    connection.execute(<<~SQL)
      INSERT INTO entries (id, company_id, version, project_id, user_id, work_date, duration, note, bill_status, review_status, discarded_at, created_at, updated_at)
      VALUES (501, 1, 3, 10, 20, '2026-01-05', 0.30000000000000004, 'first', 'billed', 'approved', NULL, '2026-01-05 10:00:00.123456', '2026-01-06 11:00:00.654321'),
             (502, 2, 1, 11, 21, '2026-01-06', 1.5, '', 'unbilled', 'not_required', '2026-02-01 00:00:00.000001', '2026-01-06 10:00:00', '2026-01-06 10:00:00');
      INSERT INTO reservations (company_id, entry_id, invoice_id, state, disposition, operation_id, created_at)
      VALUES (1, 501, 999999, 'committed', 'retained', '00000000-0000-0000-0000-000000000001', '2026-01-07 09:00:00');
      INSERT INTO invoice_operations (company_id, invoice_id, operation_id, state, desired_entry_ids, disposition, generation, created_at, finished_at)
      VALUES (1, 999999, '00000000-0000-0000-0000-000000000001', 'committed', '{501}', 'retained', 1, '2026-01-07 09:00:00', '2026-01-07 09:00:01'),
             (2, 888, '00000000-0000-0000-0000-000000000002', 'aborted', '{}', 'active', 1, '2026-01-07 09:00:00', '2026-01-07 09:00:02');
      INSERT INTO entry_audits (company_id, entry_id, actor_type, actor_id, action, before, after, entry_created_at, created_at)
      VALUES (1, 501, 'User', 20, 'create', NULL, '{"duration": 0.30000000000000004}', '2026-01-05 10:00:00.123456', '2026-01-05 10:00:00.123456'),
             (1, 501, 'User', 20, 'update', '{"note": ""}', '{"note": "first"}', '2026-01-05 10:00:00.123456', '2026-01-05 10:05:00');
      INSERT INTO idempotency_records (company_id, actor_type, actor_id, operation, key, fingerprint, status, body, created_at)
      VALUES (1, 'User', 20, 'create_entry', 'k-1', 'fp-1', 201, '{"z": 1,  "a": [ 2 ]}', '2026-01-05 10:00:00'),
             (2, 'User', 20, 'create_entry', 'k-1', 'fp-2', 201, '{"id":502}', '2026-01-06 10:00:00');
    SQL
  end

  def round_trip_rows
    {
      entries: connection.select_all("SELECT *, float8send(duration) AS duration_bits FROM entries ORDER BY company_id, id").to_a,
      reservations: connection.select_all("SELECT * FROM reservations ORDER BY company_id, entry_id, created_at").to_a,
      invoice_operations: connection.select_all("SELECT * FROM invoice_operations ORDER BY id").to_a,
      entry_audits: connection.select_all("SELECT * FROM entry_audits ORDER BY id").to_a,
      idempotency_records: connection.select_all("SELECT * FROM idempotency_records ORDER BY id").to_a
    }
  end

  # "Loading the same checkpoint twice into the monolith's prepared tables gives equal counts and checksums, and replaces rows rather than appending"
  # "Populated audit and idempotency rows survive export and load unchanged"
  it "exports, loads twice over a stray row, and leaves every prepared row exactly as exported", :without_transaction do
    round_trip_seed
    store = described_class.new(connection:)
    before = round_trip_rows
    expect(before[:entries].size).to eq(2)
    expect(before[:idempotency_records].pluck("body")).to include('{"z": 1,  "a": [ 2 ]}')

    checkpoint = store.export_checkpoint
    connection.execute(<<~SQL)
      INSERT INTO entries (id, company_id, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (777, 3, 1, 1, '2026-03-01', 9, 'unbilled', now(), now())
    SQL

    store.load_checkpoint(checkpoint)
    store.load_checkpoint(checkpoint)

    expect(round_trip_rows).to eq(before)
    expect(connection.select_value("SELECT count(*) FROM entries WHERE id = 777")).to eq(0)
    expect(store.export_checkpoint.digest).to eq(checkpoint.digest)
    expect(checkpoint.digest.dig("entries", 1, :count)).to eq(1)
    expect(checkpoint.digest.dig("entry_audits", 1, :count)).to eq(2)
    expect(checkpoint.digest.dig("idempotency_records", 2, :count)).to eq(1)
  end
end

RSpec.describe Timekeeping::Handoff::MonolithStore do
  let(:connection) { ActiveRecord::Base.connection }

  def midway_rows
    %w[entries reservations invoice_operations entry_audits idempotency_records].index_with do |table|
      connection.select_all("SELECT * FROM #{table} ORDER BY 1, 2").to_a
    end
  end

  # "A load replaces the tables in one transaction, so an interrupted load leaves them unchanged"
  it "leaves every prepared table unchanged when a load fails at the audit insert", :without_transaction do
    connection.execute(<<~SQL)
      INSERT INTO entries (id, company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (601, 1, 2, 10, 20, '2026-01-05', 4.5, 'unbilled', '2026-01-05 10:00:00', '2026-01-05 10:00:00')
    SQL
    before = midway_rows
    expect(before["entries"].pluck("id")).to eq([601])

    checkpoint_class = Timekeeping::Handoff::Checkpoint
    entry = checkpoint_class::TABLES.fetch("entries").index_with { nil }.merge(
      "id" => 900, "company_id" => 1, "version" => 1, "project_id" => 10, "user_id" => 20,
      "work_date" => Date.new(2026, 1, 9), "duration" => 1.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "proof_metadata" => {}, "created_at" => Time.utc(2026, 1, 9), "updated_at" => Time.utc(2026, 1, 9)
    )
    # Points at an entry the checkpoint does not hold, so the insert fails after
    # the entries table has already been replaced.
    orphan_audit = {
      "id" => 1, "company_id" => 1, "entry_id" => 901, "actor_type" => "User", "actor_id" => 20, "actor_name" => nil,
      "action" => "create",
      "before" => nil, "after" => { "note" => "" }, "entry_created_at" => Time.utc(2026, 1, 9), "created_at" => Time.utc(2026, 1, 9)
    }.slice(*checkpoint_class::TABLES.fetch("entry_audits"))
    tables = checkpoint_class::TABLES.keys.index_with { [] }
    tables["entries"] = [entry]
    tables["entry_audits"] = [orphan_audit]
    checkpoint = checkpoint_class.build(tables:)
    expect(checkpoint_class.verify(checkpoint)).to eq([])

    expect { described_class.new(connection:).load_checkpoint(checkpoint) }.to raise_error(StandardError)

    expect(midway_rows).to eq(before)
  end
end

RSpec.describe Timekeeping::Handoff::MonolithStore do
  let(:connection) { ActiveRecord::Base.connection }

  # "A load refuses any entry whose current version in the store is higher than its version in the checkpoint."
  it "refuses a load that would move a stored entry version backwards", :without_transaction do
    connection.execute(<<~SQL)
      INSERT INTO entries (id, company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (701, 4, 3, 10, 20, '2026-01-05', 2.0, 'unbilled', '2026-01-05 10:00:00', '2026-01-05 10:00:00')
    SQL
    store = described_class.new(connection:)
    checkpoint = store.export_checkpoint
    connection.execute("UPDATE entries SET version = 5, note = 'newer' WHERE id = 701")

    expect { store.load_checkpoint(checkpoint) }.to raise_error(/entries/)

    expect(connection.select_rows("SELECT version, note FROM entries WHERE id = 701")).to eq([[5, "newer"]])
  end
end

RSpec.describe Timekeeping::Handoff::MonolithStore do
  let(:connection) { ActiveRecord::Base.connection }

  def sequence_case_insert_entry
    connection.select_value(<<~SQL)
      INSERT INTO entries (company_id, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (1, 10, 20, '2026-01-05', 1.0, 'unbilled', now(), now()) RETURNING id
    SQL
  end

  # "A sequence only advances: it is set only if the new value is higher than its current one."
  # "Advancing the sequence to a value below the current one leaves it unchanged; a value above it raises it."
  it "advances the entry id sequence only when the target is higher", :without_transaction do
    store = described_class.new(connection:)
    first_id = sequence_case_insert_entry

    store.advance_entry_id_sequence(above: first_id - 1)
    expect(sequence_case_insert_entry).to eq(first_id + 1)

    store.advance_entry_id_sequence(above: first_id + 1)
    expect(sequence_case_insert_entry).to eq(first_id + 2)

    store.advance_entry_id_sequence(above: first_id + 100)
    expect(sequence_case_insert_entry).to eq(first_id + 101)
  end
end

